lemmas.split₂ˡ:
{X₁ = A : Obj} {Y₁ = B : Obj} {X₂ = x : Obj} {Y₂ = y : Obj}
{Z₂ = Z₃ : Obj}
{f = f₁ : A ⇒ B} {g = g₁ : y ⇒ Z₃} {h = h₁ : x ⇒ y} →
f₁ ⊗₁ (g₁ ∘ h₁) ≈ id ⊗₁ g₁ ∘ f₁ ⊗₁ h₁

lemma_normal.split₂ˡ:
{X₁ = A : Obj} {Y₁ = B : Obj} {X₂ = x : Obj} {Y₂ = y : Obj}
{Z₂ = Z₃ : Obj}
{f = f₁ : A ⇒ B} {g = g₁ : y ⇒ Z₃} {h = h₁ : x ⇒ y} →
⊗.F₁ (f₁ , g₁ ∘ h₁) ≈ ⊗.F₁ (id , g₁) ∘ ⊗.F₁ (f₁ , h₁)

